CREATE TABLE business_settings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_name text NOT NULL,address text NOT NULL,phone text NOT NULL,email text NOT NULL,primary_whatsapp text NOT NULL,secondary_whatsapp text NOT NULL,facebook text NOT NULL,instagram text NOT NULL,tiktok text NOT NULL,website text NOT NULL,opening_hours jsonb NOT NULL DEFAULT '{}'::jsonb,logo_url text NOT NULL,favicon_url text NOT NULL,theme_color text NOT NULL DEFAULT '#ec3d92',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid REFERENCES administrators(id) ON DELETE SET NULL);
CREATE UNIQUE INDEX business_settings_singleton_idx ON business_settings ((true));
CREATE TABLE payment_deposit_settings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_settings_id uuid NOT NULL REFERENCES business_settings(id) ON DELETE CASCADE,bank_name text NOT NULL,account_holder text NOT NULL,account_number_encrypted text,clabe_encrypted text,card_number_encrypted text,reference_text text NOT NULL,instructions text NOT NULL,whatsapp_number text NOT NULL,whatsapp_template text NOT NULL,show_account_number boolean NOT NULL DEFAULT false,show_clabe boolean NOT NULL DEFAULT true,show_card_number boolean NOT NULL DEFAULT false,show_bank boolean NOT NULL DEFAULT true,show_holder boolean NOT NULL DEFAULT true,is_active boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid REFERENCES administrators(id) ON DELETE SET NULL);
CREATE UNIQUE INDEX payment_deposit_business_unique ON payment_deposit_settings (business_settings_id);
